CREATE TABLE customer (customer_id INTEGER PRIMARY KEY, name TEXT, address TEXT);
CREATE TABLE product (product_id INTEGER PRIMARY KEY, name TEXT, unit_price DECIMAL);
CREATE TABLE sales_order (order_no INTEGER PRIMARY KEY, customer_id INTEGER);
CREATE TABLE line_item (
    order_no INTEGER,
    product_id INTEGER,
    qty INTEGER,
    PRIMARY KEY (order_no, product_id)
);
INSERT INTO customer VALUES (1, 'Ada Lovelace', '42 Oak St, Seattle');
INSERT INTO customer VALUES (2, 'Alan Turing', '18 Pine Ave, Portland');
INSERT INTO product VALUES (10, 'Widget A', 9.99);
INSERT INTO product VALUES (11, 'Widget B', 4.49);
INSERT INTO sales_order VALUES (1, 1);
INSERT INTO sales_order VALUES (2, 2);
INSERT INTO line_item VALUES (1, 10, 2);
INSERT INTO line_item VALUES (1, 11, 1);
INSERT INTO line_item VALUES (2, 10, 5);
SELECT so.order_no, c.name AS customer_name, p.name AS product_name, li.qty
FROM line_item AS li
JOIN sales_order AS so ON li.order_no = so.order_no
JOIN customer AS c ON so.customer_id = c.customer_id
JOIN product AS p ON li.product_id = p.product_id
ORDER BY so.order_no, p.product_id;
